#include <bits/stdc++.h>
using namespace std;

int digitSum(int x) {
    int sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ans;
    int start = max(0, n - 9 * (int)to_string(n).size());

    for (int x = start; x <= n; ++x) {
        if (x + digitSum(x) == n)
            ans.push_back(x);
    }

    cout << ans.size() << '\n';
    for (int x : ans)
        cout << x << '\n';

    return 0;
}

